export type ShopifyIntent = "cloud-networking" | "digital-security" | "data-storage" | "graphics-hardware" | "ai-compute" | "developer-input" | "maker-workspace" | "interview-audio" | "business-workspace" | "budget-workspace" | "business-operations" | "design-workspace" | "device-building" | "gaming" | "pet-care" | "garden" | "kitchen" | "home-living" | "website-services" | "automotive" | "beauty" | "workshop" | "climate" | "dental" | "legal-reading";
export type ShopifyContext = string | { path?: string; title?: string; tags?: string[]; description?: string; intent?: ShopifyIntent };
export type ShopifyProduct = {
  id: string; handle: string; title: string; description: string; productType: string; onlineStoreUrl: string; availableForSale: true;
  featuredImage: { url: string; altText: string; width: number; height: number };
  selectedOrFirstAvailableVariant: { id: string; title: string; availableForSale: true; price: { amount: string; currencyCode: string } };
};
export const STORE_ORIGIN: string;
